import{_ as t,o,c as a,ag as n}from"./chunks/framework.HG0H2VLS.js";const h=JSON.parse('{"title":"SeatingPlanner — token gaps","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/prototypes/SeatingPlanner/SeatingPlanner.token-gaps.md","filePath":"public/demos/src/prototypes/SeatingPlanner/SeatingPlanner.token-gaps.md"}'),r={name:"public/demos/src/prototypes/SeatingPlanner/SeatingPlanner.token-gaps.md"};function d(s,e,i,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="seatingplanner-—-token-gaps" tabindex="-1">SeatingPlanner — token gaps <a class="header-anchor" href="#seatingplanner-—-token-gaps" aria-label="Permalink to &quot;SeatingPlanner — token gaps&quot;">​</a></h1><p>Raw values used because no <code>--ai-*</code> token exists, recorded per <code>/build-prototype</code> tier 2. This file is the design owner&#39;s review list and the input to any later <code>/build-component</code> build, where each gap must resolve to a token or an explicit approval. Recording a gap is <strong>not</strong> minting a token.</p><table tabindex="0"><thead><tr><th>Property</th><th>Value</th><th>Element</th><th>What it is for</th></tr></thead><tbody><tr><td><code>font-family</code></td><td><code>monospace</code></td><td><code>.cmp code</code> in <code>SeatingPlannerCompare.css</code></td><td>Inline code samples on the toolbar review board. The DS has <code>--ai-font-title</code> and <code>--ai-font-body</code>, both Inter — there is no mono family, and code set in Inter is materially harder to read. A generic CSS family rather than a named face, so it is the mildest form of this gap.</td></tr><tr><td><code>--ai-icon-success</code></td><td><em>(absent)</em></td><td><code>.sp-capacity__note--warn</code>, tray empty state</td><td>Noted earlier in TASK-351550: success exists as surface/text/border but not icon. Icon-status tokens are worth adding as a set.</td></tr><tr><td><code>--ai-icon-warning</code></td><td><em>(absent)</em></td><td>5 Lucide icon strokes at <code>#F97316</code> in the mobile toolbar capture</td><td><strong>Confirmed in Figma 2026-08-05.</strong> The icon family is <code>primary · secondary · contrast · invert · invert-secondary · brand</code> — no status colours at all, so those 5 icon strokes have nowhere semantic to go and stay bound to <code>Colours/Orange/500</code>, a primitive that will not follow dark mode. Same gap as <code>--ai-icon-success</code> above: <strong>the whole <code>--ai-icon-{success,warning,error,info}</code> set is missing</strong> and is worth adding together rather than one at a time.</td></tr></tbody></table><p><strong>Also recorded, not a raw value but a naming gap:</strong> the DS has no <code>--ai-text-tertiary</code>. <code>--ai-text-contrast</code> (<code>#67676c</code>) is the dimmer-text semantic and is what dimmed metadata should use — worth knowing before someone adds a duplicate.</p>',4)])])}const g=t(r,[["render",d]]);export{h as __pageData,g as default};
